package com.example.agendapersonal;
import android.content.Context;import android.database.Cursor;import android.content.ContentValues;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.ext.junit.runners.AndroidJUnit4;
import com.example.agendapersonal.sync.*;import com.example.agendapersonal.data.DatabaseHelper;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.util.*;

/** SQLite y JSON Android reales sobre una base aislada por prueba. No utiliza la cuenta ni la base del usuario. */
@RunWith(AndroidJUnit4.class)
public class AlmacenSyncInstrumentedTest {
 static final String OWNER="00000000-0000-4000-8000-000000000001",DEVICE="00000000-0000-4000-8000-000000000002",REMOTE="00000000-0000-4000-8000-000000000003",ENTITY="00000000-0000-4000-8000-000000000004";
 Context context;AlmacenSync store;
 @Before public void crear(){context=contexto();store=new AlmacenSync(context);store.vincular("https://ejemplo.supabase.co",OWNER,null);}
 Context contexto(){return new ContextoPrueba(InstrumentationRegistry.getInstrumentation().getTargetContext(),"test_sync_"+UUID.randomUUID()+"_");}
 @After public void cerrar(){store.close();context.deleteDatabase("agenda_personal.db");}
 JSONObject persona(String nombre,int revision)throws Exception{return new JSONObject().put("id",ENTITY).put("owner_id",OWNER).put("nombre",nombre).put("otro_dato",JSONObject.NULL).put("created_at","2026-11-05T10:00:00Z").put("updated_at","2026-11-05T10:00:00Z").put("revision",revision).put("deleted_at",JSONObject.NULL);}
 CambioSync cambio(String tabla,JSONObject payload,int base)throws Exception{String id=UUID.randomUUID().toString();JSONObject j=new JSONObject().put("change_id",id).put("owner_id",OWNER).put("device_id",REMOTE).put("entity_type",tabla).put("entity_id",payload.getString("id")).put("base_revision",base).put("entity_revision",payload.getInt("revision")).put("operation",payload.isNull("deleted_at")?"UPSERT":"DELETE").put("payload",payload).put("created_at","2026-11-05T10:00:00Z");return new CambioSync(id,"2026-11-05T10:00:00Z",j.toString());}
 void insertar(Context c,JSONObject p)throws Exception{try(DatabaseHelper h=new DatabaseHelper(c)){ContentValues v=new ContentValues();Iterator<String>keys=p.keys();while(keys.hasNext()){String k=keys.next();Object valor=p.get(k);if(valor==JSONObject.NULL)v.putNull(k);else if(valor instanceof Number)v.put(k,((Number)valor).longValue());else v.put(k,valor.toString());}h.getWritableDatabase().insertOrThrow("personas",null,v);}}
 String nombre(Context c){try(DatabaseHelper h=new DatabaseHelper(c);Cursor row=h.getReadableDatabase().rawQuery("SELECT nombre FROM personas WHERE id=?",new String[]{ENTITY})){return row.moveToFirst()?row.getString(0):null;}}
 int cantidad(String tabla){try(DatabaseHelper h=new DatabaseHelper(context);Cursor row=h.getReadableDatabase().rawQuery("SELECT count(*) FROM "+tabla,null)){row.moveToFirst();return row.getInt(0);}}
 @Test public void aplicaUnaVezYNoGeneraEco()throws Exception{CambioSync c=cambio("personas",persona("Recibida",1),0);store.preparar(c,OWNER,DEVICE);assertTrue(store.aplicar(c,OWNER,DEVICE));assertTrue(store.aplicar(c,OWNER,DEVICE));assertEquals("Recibida",nombre(context));assertEquals(1,cantidad("sync_changes"));assertTrue(store.salientes(OWNER,100).isEmpty());assertEquals(1,store.recibosPendientes(OWNER,DEVICE,100).size());}
 @Test public void conflictoNoSobrescribeYConservaAmbasVersiones()throws Exception{insertar(context,persona("Local",2));CambioSync remoto=cambio("personas",persona("Recibida",2),1);store.preparar(remoto,OWNER,DEVICE);assertFalse(store.aplicar(remoto,OWNER,DEVICE));assertEquals("Local",nombre(context));assertEquals(1,store.conflictos(OWNER).size());assertTrue(store.recibosPendientes(OWNER,DEVICE,100).isEmpty());store.resolver(OWNER,DEVICE,remoto.id,true);assertEquals("Recibida",nombre(context));assertTrue(store.conflictos(OWNER).isEmpty());assertEquals(1,cantidad("sync_conflicts"));assertEquals(1,store.salientes(OWNER,100).size());}
 @Test public void resolucionConvergeAunqueLasRamasTenganRevisionesDistintas()throws Exception{insertar(context,persona("Local",3));JSONObject ramaRemota=persona("Remota",2);CambioSync remoto=cambio("personas",ramaRemota,1);store.preparar(remoto,OWNER,DEVICE);store.aplicar(remoto,OWNER,DEVICE);store.resolver(OWNER,DEVICE,remoto.id,false);CambioSync resolucion=store.salientes(OWNER,100).get(0);Context peer=contexto();try(AlmacenSync otro=new AlmacenSync(peer)){otro.vincular("https://ejemplo.supabase.co",OWNER,null);insertar(peer,ramaRemota);otro.preparar(resolucion,OWNER,REMOTE);assertTrue(otro.aplicar(resolucion,OWNER,REMOTE));assertEquals("Local",nombre(peer));assertEquals(0,otro.cantidadConflictos(OWNER));}finally{peer.deleteDatabase("agenda_personal.db");}}
 @Test public void fkFaltanteNoDejaReciboNiCambioParcial()throws Exception{JSONObject direccion=new JSONObject().put("id",UUID.randomUUID().toString()).put("owner_id",OWNER).put("persona_id",ENTITY).put("calle","Calle de prueba").put("numero","1").put("localidad","Localidad").put("provincia","Provincia").put("referencia",JSONObject.NULL).put("created_at","2026-11-05T10:00:00Z").put("updated_at","2026-11-05T10:00:00Z").put("revision",1).put("deleted_at",JSONObject.NULL);CambioSync c=cambio("direcciones",direccion,0);store.preparar(c,OWNER,DEVICE);assertFalse(store.aplicar(c,OWNER,DEVICE));assertEquals(0,cantidad("direcciones"));assertEquals(0,cantidad("sync_changes"));assertTrue(store.recibosPendientes(OWNER,DEVICE,100).isEmpty());CambioSync padre=cambio("personas",persona("Padre",1),0);store.preparar(padre,OWNER,DEVICE);store.aplicar(padre,OWNER,DEVICE);assertTrue(store.aplicar(c,OWNER,DEVICE));assertEquals(1,cantidad("direcciones"));}
 @Test public void borradoRecibidoConservaTombstoneYHistorial()throws Exception{CambioSync inicial=cambio("personas",persona("Persona",1),0);store.preparar(inicial,OWNER,DEVICE);store.aplicar(inicial,OWNER,DEVICE);JSONObject borrada=persona("Persona",2).put("deleted_at","2026-11-05T11:00:00Z");CambioSync c=cambio("personas",borrada,1);store.preparar(c,OWNER,DEVICE);assertTrue(store.aplicar(c,OWNER,DEVICE));assertEquals(1,cantidad("personas"));assertEquals(2,cantidad("sync_changes"));assertTrue(store.salientes(OWNER,100).isEmpty());}
 @Test public void columnaDesconocidaNoSeDescartaSilenciosamente()throws Exception{CambioSync c=cambio("personas",persona("Prueba",1).put("columna_futura","No descartar"),0);store.preparar(c,OWNER,DEVICE);try{store.aplicar(c,OWNER,DEVICE);fail();}catch(IllegalArgumentException esperado){}assertNull(nombre(context));assertEquals(0,cantidad("sync_changes"));assertTrue(store.recibosPendientes(OWNER,DEVICE,100).isEmpty());}
 @Test(expected=IllegalStateException.class)public void noMezclaOtraCuenta(){store.vincular("https://ejemplo.supabase.co",REMOTE,null);}
 @Test public void tiposJsonSeComparanSinConvertirNumerosEnTexto()throws Exception{assertTrue(JsonSync.iguales(new JSONObject("{\"a\":1,\"b\":null}"),new JSONObject("{\"b\":null,\"a\":1.0}")));assertFalse(JsonSync.iguales(new JSONObject("{\"a\":1}"),new JSONObject("{\"a\":\"1\"}")));}
}
